/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_cek` AS (select `a`.`idx_penelitian` AS `idx_penelitian`,`a`.`judul_penelitian` AS `judul_penelitian`,`a`.`dekripsi_penelitian` AS `dekripsi_penelitian`,`a`.`id_ref_kelompok_bidang` AS `id_ref_kelompok_bidang`,`a`.`id_ref_kategori_bidang` AS `id_ref_kategori_bidang`,`a`.`id_ref_bidang_penelitian` AS `id_ref_bidang_penelitian`,`a`.`nip_pengisi` AS `nip_pengisi`,`a`.`nama_pengisi` AS `nama_pengisi`,`a`.`email_pengisi` AS `email_pengisi`,`a`.`tahun_pengajuan` AS `tahun_pengajuan`,`a`.`semester_pengajuan` AS `semester_pengajuan`,`a`.`status_pengajuan` AS `status_pengajuan`,`a`.`dokumen_proposal` AS `dokumen_proposal`,`a`.`nilai_keseluruhan_proposal` AS `nilai_keseluruhan_proposal`,`a`.`tgl_insert` AS `tgl_insert`,`a`.`tgl_update` AS `tgl_update`,`a`.`nip_reviewer` AS `nip_reviewer`,`a`.`skema` AS `skema`,`a`.`nip_pengisi_reviewer` AS `nip_pengisi_reviewer`,`b`.`nama` AS `nama_rumpun_ilmu`,`c`.`nama` AS `nama_kategori_penelitian`,`d`.`nama` AS `nama_bidang_penelitian`,`reviewer`.`nama_reviewer` AS `nama_reviewer`,`e`.`nama_peneliti` AS `nama_peneliti`,`e`.`status_peneliti` AS `status_peneliti` from (((((`pengajuan_penelitian` `a` join `ref_kelompok_bidang` `b`) join `ref_bidang_penelitian_simlitabmas` `c`) join `ref_kategori_bidang_penelitian_simlitabmas` `d`) join `pengajuan_anggota_penelitian` `e` on(`a`.`id_ref_kelompok_bidang` = `b`.`id` and `a`.`id_ref_bidang_penelitian` = `c`.`kode_bidang_penelitian_simlitabmas` and `a`.`id_ref_kategori_bidang` = `d`.`kode_kategori_bidang_penelitian_simlitabmas` and `e`.`idx_penelitian` = `a`.`idx_penelitian`)) left join `reviewer` on(`reviewer`.`nip_reviewer` = `a`.`nip_reviewer`)) where `e`.`status_peneliti` = 'Ketua') */;

