/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_landing_page_op` AS select `v_tahun`.`tahun` AS `tahun`,if(`v_total_pengajuan`.`total_pengajuan` is null or `v_total_pengajuan`.`total_pengajuan` = '',0,`v_total_pengajuan`.`total_pengajuan`) AS `total_pengajuan`,if(`v_total_dosen_upload`.`total_dosen_upload` is null or `v_total_dosen_upload`.`total_dosen_upload` = '',0,`v_total_dosen_upload`.`total_dosen_upload`) AS `total_dosen_upload`,if(`v_total_pengajuan`.`total_pengajuan` - `v_total_dosen_upload`.`total_dosen_upload` is null,0,`v_total_pengajuan`.`total_pengajuan` - `v_total_dosen_upload`.`total_dosen_upload`) AS `total_dosen_belum_upload`,if(`v_total_proposal_reviewer`.`total_proposal_yang_sudah_ada_reviewer` is null or `v_total_proposal_reviewer`.`total_proposal_yang_sudah_ada_reviewer` = '',0,`v_total_proposal_reviewer`.`total_proposal_yang_sudah_ada_reviewer`) AS `total_proposal_reviewer`,if(`v_total_status_diterima`.`total_status_pengajuan_diterima` is null or `v_total_status_diterima`.`total_status_pengajuan_diterima` = '',0,`v_total_status_diterima`.`total_status_pengajuan_diterima`) AS `total_status_pengajuan_diterima`,if(`v_total_status_ditolak`.`total_status_pengajuan_ditolak` is null or `v_total_status_ditolak`.`total_status_pengajuan_ditolak` = '',0,`v_total_status_ditolak`.`total_status_pengajuan_ditolak`) AS `total_status_pengajuan_ditolak` from (((((`v_tahun` left join `v_total_pengajuan` on(`v_total_pengajuan`.`tahun_pengajuan` = `v_tahun`.`tahun`)) left join `v_total_dosen_upload` on(`v_total_dosen_upload`.`tahun_pengajuan` = `v_tahun`.`tahun`)) left join `v_total_proposal_reviewer` on(`v_total_proposal_reviewer`.`tahun_pengajuan` = `v_tahun`.`tahun`)) left join `v_total_status_diterima` on(`v_total_status_diterima`.`tahun_pengajuan` = `v_tahun`.`tahun`)) left join `v_total_status_ditolak` on(`v_total_status_ditolak`.`tahun_pengajuan` = `v_tahun`.`tahun`)) */;

